using System.IO;
using System.Diagnostics;
namespace DesktopBox;
internal static class CrashTest {
 internal static int Run(){var testRoot=Path.Combine(Path.GetTempPath(),"DesktopBox-CrashTest-"+Guid.NewGuid());Store.PathName=Path.Combine(testRoot,"state.json");var file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"DesktopBox-CrashTest-"+Guid.NewGuid()+".txt");Process? hold=null,watch=null;try{File.WriteAllText(file,"recovery test");Thread.Sleep(2000);var original=DesktopIcons.Inspect(file);hold=Launch("--layer-hold",file);for(int i=0;i<50&&!File.Exists(file+".ready");i++)Thread.Sleep(100);if(!File.Exists(file+".ready"))throw new Exception("Hide process did not become ready");watch=Launch("--watch",hold.Id.ToString());Thread.Sleep(500);hold.Kill();hold.WaitForExit();if(!watch.WaitForExit(10000))throw new Exception("Watchdog timed out");var actual=DesktopIcons.Inspect(file);if(!DesktopLayer.NativeVisible||actual.X!=original.X||actual.Y!=original.Y||!File.Exists(file))throw new Exception("Recovery mismatch");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"crash-test.txt"),"PASS: helper restored native desktop visibility and exact original icon position after process killed; file unchanged");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"crash-test.txt"),ex.ToString());return 1;}finally{if(hold is{HasExited:false})hold.Kill();if(watch is{HasExited:false})watch.WaitForExit(5000);DesktopIcons.Recover();File.Delete(file);File.Delete(file+".ready");hold?.Dispose();watch?.Dispose();if(Directory.Exists(testRoot))Directory.Delete(testRoot,true);}}
 static Process Launch(params string[] args){var info=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};if(Path.GetFileNameWithoutExtension(info.FileName).Equals("dotnet",StringComparison.OrdinalIgnoreCase))info.ArgumentList.Add(typeof(Program).Assembly.Location);info.Environment["DESKTOPBOX_TEST_STATE"]=Store.PathName;foreach(var arg in args)info.ArgumentList.Add(arg);return Process.Start(info)!;}
}
